{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The training loss and the accuracy on both sets after each epoch.",
  "transform": [
    {
      "fold": [
        "loss",
        "train_accuracy",
        "held_out_accuracy"
      ],
      "as": [
        "measure",
        "value"
      ]
    }
  ],
  "mark": {
    "type": "line",
    "point": true
  },
  "encoding": {
    "x": {
      "field": "epoch",
      "type": "quantitative",
      "title": "Epoch",
      "axis": {
        "tickMinStep": 1
      }
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": null
    },
    "color": {
      "field": "measure",
      "type": "nominal",
      "title": null,
      "sort": [
        "loss",
        "train_accuracy",
        "held_out_accuracy"
      ]
    },
    "tooltip": [
      {
        "field": "epoch"
      },
      {
        "field": "measure"
      },
      {
        "field": "value",
        "format": ".3f"
      }
    ]
  }
}
